'use client';

/**
 * Catalogue maintenance: add a title, edit it, and manage its physical copies.
 *
 * Kept separate from the lending desk because they are different jobs done at
 * different times — cataloguing happens when a box of books arrives, lending
 * happens all day. Merging them would put a form nobody needs in front of the
 * person at the counter.
 *
 * Accession numbers are generated by the server. The form asks how many copies
 * arrived, not what to call them, because a librarian numbering by hand is how
 * duplicates get created.
 */

import { useCallback, useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { Card, Badge, EmptyState } from '../../../components/ui.tsx';
import {
  Field,
  TextInput,
  TextArea,
  Select,
  CheckboxRow,
  ErrorBanner,
  SuccessBanner,
  SubmitButton,
  SecondaryButton,
  Disclosure,
  useSubmit,
} from '../../../components/form.tsx';

type Labels = Record<string, string>;

type Item = {
  id: string;
  title: string;
  author: string | null;
  isbn: string | null;
  itemType: string;
  category: string | null;
  callNumber: string | null;
  language: string | null;
  active: boolean;
  totalCopies: number;
  availableCopies: number;
};

type Copy = {
  id: string;
  accessionNumber: string;
  status: string;
  condition: string;
  acquiredOn: string | null;
  note: string | null;
  loanId: string | null;
  borrowerName: string | null;
  dueOn: string | null;
};

type Draft = {
  title: string;
  author: string;
  isbn: string;
  publisher: string;
  publishedYear: string;
  itemType: string;
  category: string;
  callNumber: string;
  language: string;
  description: string;
  active: boolean;
};

const EMPTY: Draft = {
  title: '',
  author: '',
  isbn: '',
  publisher: '',
  publishedYear: '',
  itemType: 'book',
  category: '',
  callNumber: '',
  language: '',
  description: '',
  active: true,
};

function fill(template: string, values: Record<string, string>): string {
  return template.replace(/\{(\w+)\}/g, (m, k: string) => values[k] ?? m);
}

/** Blank optional text becomes null so the server stores absence, not ''. */
function orNull(value: string): string | null {
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : null;
}

export default function CatalogueManager({
  labels,
  itemTypes,
  conditions,
  copyStatuses,
  items,
  today,
}: {
  labels: Labels;
  itemTypes: string[];
  conditions: string[];
  copyStatuses: string[];
  items: Item[];
  today: string;
}) {
  const t = useCallback((key: string) => labels[key] ?? key, [labels]);
  const router = useRouter();

  const [creating, setCreating] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [copiesFor, setCopiesFor] = useState<string | null>(null);

  return (
    <Card title={t('ops.manage')}>
      <Disclosure
        open={creating}
        onToggle={(next) => {
          setCreating(next);
          setEditingId(null);
        }}
        openLabel={t('library.newItem')}
        closeLabel={t('action.cancel')}
      >
        <ItemForm
          labels={labels}
          t={t}
          itemTypes={itemTypes}
          initial={EMPTY}
          onDone={() => {
            setCreating(false);
            router.refresh();
          }}
        />
      </Disclosure>

      {items.length === 0 ? (
        <div className="mt-4">
          <EmptyState title={t('library.noItems')} description={t('library.newItemHelp')} />
        </div>
      ) : (
        <ul className="mt-4 divide-y divide-ink-100">
          {items.map((item) => (
            <li key={item.id} className="py-3">
              <div className="flex flex-wrap items-start justify-between gap-2">
                <div className="min-w-0 flex-1">
                  <p className="truncate text-sm font-medium text-ink-900">
                    {item.title}
                    {!item.active && (
                      <span className="ml-2">
                        <Badge tone="neutral">{t('library.inactive')}</Badge>
                      </span>
                    )}
                  </p>
                  <p className="truncate text-xs text-ink-500">
                    {[item.author, item.callNumber].filter(Boolean).join(' · ') || '—'}
                  </p>
                </div>
                <div className="flex shrink-0 items-center gap-2">
                  <Badge tone={item.availableCopies > 0 ? 'good' : 'warn'}>
                    {item.availableCopies}/{item.totalCopies}
                  </Badge>
                  <button
                    type="button"
                    onClick={() => {
                      setEditingId(editingId === item.id ? null : item.id);
                      setCopiesFor(null);
                    }}
                    className="tap-target rounded-lg border border-ink-300 px-3 py-1.5 text-xs font-medium text-ink-700 hover:bg-ink-50"
                  >
                    {t('action.edit')}
                  </button>
                  <button
                    type="button"
                    onClick={() => {
                      setCopiesFor(copiesFor === item.id ? null : item.id);
                      setEditingId(null);
                    }}
                    className="tap-target rounded-lg border border-ink-300 px-3 py-1.5 text-xs font-medium text-ink-700 hover:bg-ink-50"
                  >
                    {t('library.copies')}
                  </button>
                </div>
              </div>

              {editingId === item.id && (
                <div className="mt-3 rounded-lg border border-ink-200 bg-ink-50 p-3">
                  <ItemForm
                    labels={labels}
                    t={t}
                    itemTypes={itemTypes}
                    itemId={item.id}
                    initial={{
                      title: item.title,
                      author: item.author ?? '',
                      isbn: item.isbn ?? '',
                      publisher: '',
                      publishedYear: '',
                      itemType: item.itemType,
                      category: item.category ?? '',
                      callNumber: item.callNumber ?? '',
                      language: item.language ?? '',
                      description: '',
                      active: item.active,
                    }}
                    onDone={() => {
                      setEditingId(null);
                      router.refresh();
                    }}
                  />
                </div>
              )}

              {copiesFor === item.id && (
                <div className="mt-3 rounded-lg border border-ink-200 bg-ink-50 p-3">
                  <CopyManager
                    labels={labels}
                    t={t}
                    itemId={item.id}
                    conditions={conditions}
                    copyStatuses={copyStatuses}
                    today={today}
                  />
                </div>
              )}
            </li>
          ))}
        </ul>
      )}
    </Card>
  );
}

// ---------------------------------------------------------------------------
// Title form — used for both create and edit
// ---------------------------------------------------------------------------

function ItemForm({
  labels,
  t,
  itemTypes,
  initial,
  itemId,
  onDone,
}: {
  labels: Labels;
  t: (k: string) => string;
  itemTypes: string[];
  initial: Draft;
  itemId?: string;
  onDone: () => void;
}) {
  const { saving, error, fieldErrors, submit } = useSubmit();
  const [draft, setDraft] = useState<Draft>(initial);
  const [success, setSuccess] = useState<string | null>(null);

  function set<K extends keyof Draft>(key: K, value: Draft[K]) {
    setDraft((prev) => ({ ...prev, [key]: value }));
  }

  async function save(event: React.FormEvent) {
    event.preventDefault();
    setSuccess(null);

    const year = draft.publishedYear.trim();
    const body = {
      title: draft.title.trim(),
      author: orNull(draft.author),
      isbn: orNull(draft.isbn),
      publisher: orNull(draft.publisher),
      // An empty year must be absent, not 0 — see emptyToNull in the schema.
      publishedYear: year ? Number(year) : null,
      itemType: draft.itemType,
      category: orNull(draft.category),
      callNumber: orNull(draft.callNumber),
      language: orNull(draft.language),
      description: orNull(draft.description),
      active: draft.active,
    };

    const result = itemId
      ? await submit(`/api/library/items/${itemId}`, { method: 'PATCH', body })
      : await submit('/api/library/items', { method: 'POST', body });

    if (!result) return;
    setSuccess(t('library.itemSaved'));
    if (!itemId) setDraft(EMPTY);
    onDone();
  }

  return (
    <form onSubmit={save} className="space-y-4">
      <div className="grid gap-4 sm:grid-cols-2">
        <Field
          label={t('library.item')}
          htmlFor={`title-${itemId ?? 'new'}`}
          error={fieldErrors.title}
          required
          className="sm:col-span-2"
        >
          <TextInput
            id={`title-${itemId ?? 'new'}`}
            value={draft.title}
            onChange={(e) => set('title', e.target.value)}
            required
            maxLength={300}
            invalid={Boolean(fieldErrors.title)}
          />
        </Field>

        <Field label={t('library.author')} error={fieldErrors.author}>
          <TextInput
            value={draft.author}
            onChange={(e) => set('author', e.target.value)}
            maxLength={200}
          />
        </Field>

        <Field label={t('library.itemType')} error={fieldErrors.itemType}>
          <Select value={draft.itemType} onChange={(e) => set('itemType', e.target.value)}>
            {itemTypes.map((type) => (
              <option key={type} value={type}>
                {t(`library.itemType.${type}`)}
              </option>
            ))}
          </Select>
        </Field>

        <Field label={t('library.isbn')} error={fieldErrors.isbn}>
          <TextInput
            value={draft.isbn}
            onChange={(e) => set('isbn', e.target.value)}
            maxLength={32}
            inputMode="numeric"
          />
        </Field>

        <Field label={t('library.callNumber')} error={fieldErrors.callNumber}>
          <TextInput
            value={draft.callNumber}
            onChange={(e) => set('callNumber', e.target.value)}
            maxLength={64}
          />
        </Field>

        <Field label={t('library.publisher')} error={fieldErrors.publisher}>
          <TextInput
            value={draft.publisher}
            onChange={(e) => set('publisher', e.target.value)}
            maxLength={200}
          />
        </Field>

        <Field label={t('library.publishedYear')} error={fieldErrors.publishedYear}>
          <TextInput
            value={draft.publishedYear}
            onChange={(e) => set('publishedYear', e.target.value.replace(/\D/g, ''))}
            inputMode="numeric"
            maxLength={4}
            invalid={Boolean(fieldErrors.publishedYear)}
          />
        </Field>

        <Field label={t('library.category')} error={fieldErrors.category}>
          <TextInput
            value={draft.category}
            onChange={(e) => set('category', e.target.value)}
            maxLength={120}
          />
        </Field>

        <Field label={t('library.language')} error={fieldErrors.language}>
          <TextInput
            value={draft.language}
            onChange={(e) => set('language', e.target.value)}
            maxLength={32}
          />
        </Field>

        <Field
          label={t('library.description')}
          error={fieldErrors.description}
          className="sm:col-span-2"
        >
          <TextArea
            value={draft.description}
            onChange={(e) => set('description', e.target.value)}
            maxLength={2000}
          />
        </Field>
      </div>

      <CheckboxRow
        id={`active-${itemId ?? 'new'}`}
        label={t('library.active')}
        checked={draft.active}
        onChange={(next) => set('active', next)}
      />

      <ErrorBanner message={error} />
      {!error && <SuccessBanner message={success} />}

      <div className="flex flex-wrap gap-2">
        <SubmitButton
          saving={saving}
          savingLabel={labels['ops.saving'] ?? '…'}
          disabled={draft.title.trim().length === 0}
        >
          {t('action.save')}
        </SubmitButton>
      </div>
    </form>
  );
}

// ---------------------------------------------------------------------------
// Copies
// ---------------------------------------------------------------------------

function CopyManager({
  labels,
  t,
  itemId,
  conditions,
  copyStatuses,
  today,
}: {
  labels: Labels;
  t: (k: string) => string;
  itemId: string;
  conditions: string[];
  copyStatuses: string[];
  today: string;
}) {
  const router = useRouter();
  const { saving, error, fieldErrors, submit } = useSubmit();

  const [copies, setCopies] = useState<Copy[] | null>(null);
  const [count, setCount] = useState('1');
  const [prefix, setPrefix] = useState('');
  const [condition, setCondition] = useState('good');
  const [acquiredOn, setAcquiredOn] = useState(today);
  const [success, setSuccess] = useState<string | null>(null);

  const load = useCallback(async () => {
    const res = await fetch(`/api/library/items/${itemId}`);
    if (res.ok) {
      const body = await res.json();
      setCopies(body.copies ?? []);
    }
  }, [itemId]);

  // Load once when the panel opens.
  useEffect(() => {
    void load();
  }, [load]);

  async function addCopies(event: React.FormEvent) {
    event.preventDefault();
    setSuccess(null);

    const result = await submit<{ added: number; from: string | null }>(
      `/api/library/items/${itemId}/copies`,
      {
        method: 'POST',
        body: {
          count: Number(count) || 0,
          prefix: prefix.trim() || null,
          condition,
          acquiredOn: acquiredOn || null,
        },
      },
    );
    if (!result) return;

    setSuccess(
      fill(labels['library.copiesAdded'] ?? '', {
        count: String(result.added),
        from: result.from ?? '—',
      }),
    );
    setCount('1');
    await load();
    router.refresh();
  }

  async function setStatus(copy: Copy, status: string) {
    setSuccess(null);
    const result = await submit(`/api/library/copies/${copy.id}`, {
      method: 'PATCH',
      body: {
        accessionNumber: copy.accessionNumber,
        status,
        condition: copy.condition,
        acquiredOn: copy.acquiredOn,
        note: copy.note,
      },
    });
    if (!result) return;
    setSuccess(t('library.copySaved'));
    await load();
    router.refresh();
  }

  return (
    <div className="space-y-4">
      <form onSubmit={addCopies} className="space-y-3">
        <div className="grid gap-3 sm:grid-cols-4">
          <Field label={t('library.copyCount')} error={fieldErrors.count} required>
            <TextInput
              value={count}
              onChange={(e) => setCount(e.target.value.replace(/\D/g, ''))}
              inputMode="numeric"
              required
              invalid={Boolean(fieldErrors.count)}
            />
          </Field>
          <Field label={t('library.copyPrefix')} hint={t('library.copyPrefixHelp')}>
            <TextInput value={prefix} onChange={(e) => setPrefix(e.target.value)} maxLength={32} />
          </Field>
          <Field label={t('library.condition')}>
            <Select value={condition} onChange={(e) => setCondition(e.target.value)}>
              {conditions.map((c) => (
                <option key={c} value={c}>
                  {t(`library.condition.${c}`)}
                </option>
              ))}
            </Select>
          </Field>
          <Field label={t('library.acquiredOn')} error={fieldErrors.acquiredOn}>
            <TextInput
              type="date"
              value={acquiredOn}
              onChange={(e) => setAcquiredOn(e.target.value)}
            />
          </Field>
        </div>

        <SubmitButton
          saving={saving}
          savingLabel={labels['ops.saving'] ?? '…'}
          disabled={!count || Number(count) < 1}
        >
          {t('library.addCopies')}
        </SubmitButton>
      </form>

      <ErrorBanner message={error} />
      {!error && <SuccessBanner message={success} />}

      {copies === null ? (
        <p className="text-xs text-ink-500">{t('ops.loading')}</p>
      ) : copies.length === 0 ? (
        <p className="text-xs text-ink-500">{t('library.noCopies')}</p>
      ) : (
        <ul className="divide-y divide-ink-100">
          {copies.map((copy) => (
            <li key={copy.id} className="flex flex-wrap items-center justify-between gap-2 py-2">
              <span className="min-w-0">
                <span className="block font-mono text-xs text-ink-800">
                  {copy.accessionNumber}
                </span>
                {copy.loanId && (
                  <span className="block text-xs text-ink-500">
                    {fill(labels['library.onLoanTo'] ?? '', {
                      name: copy.borrowerName ?? '—',
                    })}
                  </span>
                )}
              </span>
              <span className="flex shrink-0 items-center gap-1.5">
                <Badge
                  tone={
                    copy.loanId
                      ? 'info'
                      : copy.status === 'available'
                        ? 'good'
                        : copy.status === 'lost'
                          ? 'bad'
                          : 'warn'
                  }
                >
                  {copy.loanId ? t('library.onLoan') : t(`library.copyStatus.${copy.status}`)}
                </Badge>
                {/* A copy that is out cannot be re-classified underneath the
                    borrower; return it first. */}
                {!copy.loanId && (
                  <Select
                    aria-label={t('library.copyStatus')}
                    value={copy.status}
                    disabled={saving}
                    onChange={(e) => void setStatus(copy, e.target.value)}
                    className="!w-auto !py-1.5 !text-xs"
                  >
                    {copyStatuses.map((s) => (
                      <option key={s} value={s}>
                        {t(`library.copyStatus.${s}`)}
                      </option>
                    ))}
                  </Select>
                )}
              </span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
